import pandas as pd
import pytz
from datetime import datetime
from random import randint, seed as set_seed

def task_func(
    utc_datetime,
    cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney'],
    weather_conditions=['Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'],
    timezones={
        'New York': 'America/New_York',
        'London': 'Europe/London',
        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    if not isinstance(utc_datetime, datetime):
        raise ValueError('utc_datetime must be a datetime object with tzinfo set to UTC.')

    for city in cities:
        if city not in timezones:
            raise ValueError(f'Timezone for {city} not provided in timezones parameter.')

    set_seed(seed)

    utc_tz = pytz.UTC
    if utc_datetime.tzinfo is None:
        utc_datetime = utc_tz.localize(utc_datetime)
    else:
        utc_datetime = utc_datetime.astimezone(utc_tz)

    report_data = []

    for city in cities:
        tz_name = timezones[city]
        local_tz = pytz.timezone(tz_name)
        local_time = utc_datetime.astimezone(local_tz)

        local_time_str = local_time.strftime('%Y-%m-%d %H:%M:%S %Z')

        weather = weather_conditions[randint(0, len(weather_conditions) - 1)]

        report_data.append({
            'City': city,
            'Local Time': local_time_str,
            'Weather Condition': weather
        })

    return pd.DataFrame(report_data)

